for p in (R/'right_hand_rotation_20261030/yaw_roundtrip/operator_guide.html',R/'right_hand_rotation_20261030/single_forward/operator_guide.html'):
 s=p.read_text(encoding='utf-8');mark='<!-- current-grasp-review-20261030 -->'
 if mark not in s:
  banner=mark+'<aside style="padding:16px;margin:16px;border:2px solid #d49b16;background:#fff5d9;color:#192631"><b>현재: 회전 뒤 몸통 고정을 보완 중.</b> 이 페이지의 이전 실행 안내는 대기 상태입니다. 같은 동작을 반복 실행하지 말고 <a href="../four_forward_review/index.html">네 번의 실제 결과와 새 고정 동작 검토</a>를 확인하세요. 새 실물 실행 명령은 아직 없습니다.</aside>'
  i=s.lower().find('<body');end=s.find('>',i) if i>=0 else -1
  s=s[:end+1]+banner+s[end+1:] if end>=0 else banner+s;p.write_text(s,encoding='utf-8')
